<script setup lang="ts">import{reactive,ref}from'vue';import ProductIdentityDisplay from './ProductIdentityDisplay.vue';import ChineseDatePicker from'./ChineseDatePicker.vue';import{shipAfterSales,type AfterSalesDetail}from'../api/after-sales';const props=defineProps<{detail:AfterSalesDetail}>(),emit=defineEmits<{close:[];saved:[];message:[text:string,kind?:'success'|'error']}>();const date=ref(new Date().toISOString().slice(0,10)),carrier=ref(''),trackingNo=ref('');const items=reactive(props.detail.replacementLines.map(x=>({line:x,quantity:0})));async function submit(){if(!trackingNo.value.trim()){emit('message','物流单号不能为空','error');return}try{await shipAfterSales(props.detail.id,{shipmentDate:date.value,carrier:carrier.value,trackingNo:trackingNo.value,version:props.detail.version,items:items.filter(x=>x.quantity>0).map(x=>({replacementLineId:x.line.id,quantity:x.quantity}))});emit('saved')}catch(e){emit('message',e instanceof Error?e.message:'发货失败','error')}}</script><template><div class="dialog-mask"><section class="dialog-card after-sales-action-dialog"><header><div><h2>换货发出</h2><p>按可用库存扣减，支持分批发货</p></div><button @click="emit('close')">关闭</button></header><div class="after-sales-body"><div class="form-grid"><label><span>发货日期</span><ChineseDatePicker v-model="date" /></label><label><span>物流公司</span><input v-model="carrier"></label><label><span>物流单号</span><input v-model="trackingNo"></label></div><div v-for="x in items" :key="x.line.id" class="after-sales-quality-line"><ProductIdentityDisplay compact :product-code="x.line.productCode" :customer-part-number="x.line.customerPartNumber" :model="x.line.model" /><span>待发 {{x.line.plannedQuantity-(x.line.shippedQuantity??0)}} · 可用 {{x.line.availableQuantity??0}}</span><label>本次发出<input v-model.number="x.quantity" type="number" min="0" :max="x.line.plannedQuantity-(x.line.shippedQuantity??0)"></label></div></div><footer class="dialog-actions"><button class="secondary-action" @click="emit('close')">取消操作</button><button class="primary-action" @click="submit">确认发货</button></footer></section></div></template>
